styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  grid-template-rows: 1fr auto auto 1fr;
  align-items: start;
  column-gap: var(--g-gap);
  min-height: calc(var(--vh, 1vh) * 120);
}
section[data-skill-hub] .-w .note {
  grid-column-start: 1;
  grid-column-end: 15;
   grid-row-start: 1;
  justify-self: center; 
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: var(--h0);
  background-color: var(--c-black);
}
section[data-skill-hub] .-w .image-bg {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  grid-row-end: 5;
  margin-top: calc( var(--vh,1vh) * 50 );

}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w .image-bg {
    grid-column-start: 3;
    grid-column-end: 13;
    margin-top: min(calc( var(--vh,1vh) * 50 ), calc( var(--vw,1lvw) * 50 ));
  }
}
section[data-skill-hub] .-w .image-1 {
  grid-column-start: 3;
  grid-column-end: 13;
  grid-row-start: 1;
  grid-row-end: 5;
  margin-top: calc( var(--vh,1vh) * 25 );
  z-index: 20;

}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w .image-1 {
    grid-column-start: 6;
    grid-column-end: 10;
    margin-top: min(calc( var(--vh,1vh) * 15 ), calc( var(--vw,1lvw) * 50 ));
  }
}
section[data-skill-hub] .-w .title {
  grid-column-start: 1;
  grid-column-end: 15;

  align-self: center;
  text-align: center;
  color: var(--c-black);
  position: relative;
}
section[data-skill-hub] .-w .line-1 {
  grid-row-start: 2;
  z-index: 20;
  margin-top: calc( var(--vh,1vh) * 35 );
  margin-bottom: 1em;
}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w .line-1 {
    margin-top: initial;
    margin-bottom: initial;
    margin-top: calc( var(--vh,1vh) * 5 );
  }
}
section[data-skill-hub] .-w .line-2 {
  grid-row-start: 3;
  z-index: 20;

}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w .line-2 {
    z-index: initial;
    margin-top: 0.5em;
  }
}
